@namespace sv_ca596480bdc4486ca0c872c344b44a9c.Components.Pages.Board

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1"><small class="text-muted">@Task.Assignee</small></p>
        <span class="badge @PriorityClass">@Task.Priority</span>
        <small class="text-muted ms-2">@Task.DueDate.ToString("MMM dd")</small>
        <div class="mt-2">
            @if (CanMoveLeft)
            {
                <button class="btn btn-sm btn-outline-secondary me-1" @onclick="OnMoveLeft" disabled="@IsMoving">← Move Left</button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-sm btn-outline-secondary" @onclick="OnMoveRight" disabled="@IsMoving">Move Right →</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeftClicked { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRightClicked { get; set; }

    private bool IsMoving;

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async System.Threading.Tasks.Task OnMoveLeft()
    {
        IsMoving = true;
        await OnMoveLeftClicked.InvokeAsync(Task);
        IsMoving = false;
    }

    private async System.Threading.Tasks.Task OnMoveRight()
    {
        IsMoving = true;
        await OnMoveRightClicked.InvokeAsync(Task);
        IsMoving = false;
    }
}

@namespace sv_ca596480bdc4486ca0c872c344b44a9c.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn btn-sm btn-primary w-100" @onclick="Show">+ Add Task</button>
}
else
{
    <div class="card mt-2">
        <div class="card-body p-2">
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="Title" />
            </div>
            <div class="mb-2">
                <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="Assignee" />
            </div>
            <div class="mb-2">
                <select class="form-select form-select-sm" @bind="Priority">
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                </select>
            </div>
            <div class="mb-2">
                <input type="date" class="form-control form-control-sm" @bind="DueDate" />
            </div>
            <div class="d-flex gap-1">
                <button class="btn btn-sm btn-success" @onclick="Save" disabled="@IsSaving">Save</button>
                <button class="btn btn-sm btn-secondary" @onclick="Cancel">Cancel</button>
            </div>
            @if (!string.IsNullOrEmpty(Error))
            {
                <div class="text-danger mt-1"><small>@Error</small></div>
            }
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool IsVisible;
    private bool IsSaving;
    private string Title = "";
    private string Assignee = "";
    private string Priority = "Medium";
    private DateTime DueDate = DateTime.Today.AddDays(7);
    private string? Error;

    private void Show() => IsVisible = true;

    private void Cancel()
    {
        IsVisible = false;
        ResetForm();
    }

    private async System.Threading.Tasks.Task Save()
    {
        if (string.IsNullOrWhiteSpace(Title))
        {
            Error = "Title is required.";
            return;
        }

        Error = null;
        IsSaving = true;
        try
        {
            await OnTaskCreated.InvokeAsync(new TaskItem(0, Title, Assignee, Priority, DueDate, Status));
            IsVisible = false;
            ResetForm();
        }
        catch (Exception ex)
        {
            Error = ex.Message;
        }
        finally
        {
            IsSaving = false;
        }
    }

    private void ResetForm()
    {
        Title = "";
        Assignee = "";
        Priority = "Medium";
        DueDate = DateTime.Today.AddDays(7);
        Error = null;
    }
}

@namespace sv_ca596480bdc4486ca0c872c344b44a9c.Components.Pages.Board

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@ColumnName</strong>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body overflow-auto" style="max-height: 70vh;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          OnMoveLeftClicked="HandleMoveLeft"
                          OnMoveRightClicked="HandleMoveRight" />
            }
            <AddTaskForm Status="@Status" OnTaskCreated="OnTaskCreated" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(TaskItem Task, string Direction)> OnTaskMoved { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private async System.Threading.Tasks.Task HandleMoveLeft(TaskItem task)
    {
        await OnTaskMoved.InvokeAsync((task, "left"));
    }

    private async System.Threading.Tasks.Task HandleMoveRight(TaskItem task)
    {
        await OnTaskMoved.InvokeAsync((task, "right"));
    }
}

@namespace sv_ca596480bdc4486ca0c872c344b44a9c.Components.Pages.Board

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Search tasks by title..."
           value="@SearchText" @oninput="OnInput" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = "";
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async System.Threading.Tasks.Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}

