+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetFilteredTasks(string status)
+    {
+        var tasks = allTasks.Where(t => t.Status == status);
+        if (!string.IsNullOrWhiteSpace(searchText))
+        {
+            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
+        }
+        return tasks.ToList();
+    }
+
+    private void OnSearchChanged(string value)
+    {
+        searchText = value;
+    }
+
+    private async System.Threading.Tasks.Task HandleTaskMoved((TaskItem Task, string Direction) args)
+    {
+        var currentIndex = Array.IndexOf(Statuses, args.Task.Status);
+        var newIndex = args.Direction == "left" ? currentIndex - 1 : currentIndex + 1;
+
+        if (newIndex < 0 || newIndex >= Statuses.Length) return;
+
+        var newStatus = Statuses[newIndex];
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(args.Task.Id, newStatus);
+            var index = allTasks.FindIndex(t => t.Id == args.Task.Id);
+            if (index >= 0)
+            {
+                allTasks[index] = args.Task with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+
+    private async System.Threading.Tasks.Task HandleTaskCreated(TaskItem formData)
+    {
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
+            allTasks.Add(created);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+    }
+}
+

